#!/bin/sh
# One-shot: load the stock Guacamole schema (generated by the guacamole image) if the DB is
# empty, then neutralise guacadmin and create the bootstrap SAML admin.
set -eu
export PGPASSWORD="$GUACAMOLE_DB_PASSWORD"
PSQL="psql -v ON_ERROR_STOP=1 -h postgres -U guacamole -d guacamole"

if [ "$($PSQL -tAc "SELECT to_regclass('public.guacamole_user') IS NOT NULL")" != "t" ]; then
  $PSQL -f /schema/initdb.sql
fi
$PSQL -v admin_user="$GUAC_BOOTSTRAP_ADMIN" -f /postgres/guacamole-bootstrap.sql
echo "guacamole db ready"
